import json
from collections import Counter
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
LOG_FILE = BASE_DIR / "app.log"
REPORT_FILE = BASE_DIR / "report.json"
LEVELS = ("INFO", "WARN", "ERROR")


def count_levels(log_path):
    counts = Counter()
    for line in log_path.read_text(encoding="utf-8").splitlines():
        fields = line.split()
        if fields and fields[0] in LEVELS:
            counts[fields[0]] += 1
    return counts


def build_report(log_path):
    counts = count_levels(log_path)
    return {level: counts.get(level, 0) for level in LEVELS}


def main():
    report = build_report(LOG_FILE)
    REPORT_FILE.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(report))


if __name__ == "__main__":
    main()

